import sys, os, json, uuid
from datetime import datetime, timezone
sys.path.insert(0, '/data/scripts')
import requests as req

FLOWSINT_URL = os.environ.get('FLOWSINT_API_URL', 'http://flowsint-api-prod:5001').rstrip('/')
FLOWSINT_KEY = os.environ.get('FLOWSINT_API_KEY', '')
HJ = {'Authorization': f'Bearer {FLOWSINT_KEY}', 'Content-Type': 'application/json'}

item = _items[0].get('json', {}) if _items else {}
body = item.get('body', item) if isinstance(item.get('body'), dict) else item
if not isinstance(body, dict):
    body = {}

campaign_id = str(body.get('campaign_id') or '').strip()
company_name = str(body.get('company_name') or '').strip()
company_id = str(body.get('company_id') or '').strip()
linkedin_url = str(body.get('linkedin_url') or '').strip()
mark_fp = bool(body.get('mark_fp', False))
note = str(body.get('note') or '').strip()

# Initialize debug log early so validation errors can reference it
_debug_log = []
def _dbg(msg):
    _debug_log.append(str(msg))

if not campaign_id:
    return [{'json': {'statusCode': 200, 'body': {'status': 'error', 'error': 'campaign_id required'}}}]

if not company_name and not company_id:
    return [{'json': {'statusCode': 200, 'body': {'status': 'error', 'error': 'company_name or company_id required'}}}]

if not linkedin_url and not mark_fp:
    return [{'json': {'statusCode': 200, 'body': {'status': 'error', 'error': 'linkedin_url required (or set mark_fp=true to clear)'}}}]

sketch_id = campaign_id
now = datetime.now(timezone.utc).isoformat()

# ── DEBUG LOGGING (inline, returned in error responses) ──
import traceback as _tb

_dbg(f"=== WF31 called at {now} ===")
_dbg(f"campaign_id={campaign_id!r}, company_name={company_name!r}, company_id={company_id!r}")
_dbg(f"linkedin_url={linkedin_url!r}, mark_fp={mark_fp!r}, note={note!r}")
_dbg(f"sketch_id={sketch_id!r}")
_dbg('Variables initialized OK')
_dbg(f"FLOWSINT_URL={FLOWSINT_URL!r}")

# Validate sketch_id is a valid UUID before calling Flowsint
try:
    import uuid as _uuid_mod
    _uuid_mod.UUID(sketch_id)
except (ValueError, AttributeError):
    _dbg(f'INVALID sketch_id (not a UUID): {sketch_id!r}')
    return [{'json': {'statusCode': 200, 'body': {'status': 'error', 'error': f'Invalid campaign_id: not a valid UUID: {sketch_id!r}. The recon data may be stale — try re-running Domain Recon first.', 'debug': _debug_log}}}]

# Get existing node by ID if provided, otherwise create/find by name
node = None
node_id = None
node_label = None

if company_id:
    try:
        r = req.get(f'{FLOWSINT_URL}/api/sketches/{sketch_id}/nodes/{company_id}', headers=HJ, timeout=10)
        if r.ok:
            node = r.json().get('node')
            node_id = node.get('id')
            node_label = node.get('nodeLabel', '')
    except Exception as e:
        pass

# If no node found by ID, create it (Flowsint MERGEs on nodeLabel)
if not node:
    try:
        create_payload = {
            'id': str(uuid.uuid4()),
            'nodeLabel': company_name or 'Unknown Company',
            'nodeType': 'Company',
            'nodeMetadata': {},
            'nodeProperties': {
                'name': company_name or 'Unknown Company',
                'relationship': 'target',
                'source': 'manual-override',
                'discovered_at': now
            }
        }
        cr = req.post(f'{FLOWSINT_URL}/api/sketches/{sketch_id}/nodes/add', headers=HJ,
                      json=create_payload, timeout=10)
        if cr.ok:
            node = (cr.json().get('node') or cr.json())
            node_id = node.get('id')
            node_label = node.get('nodeLabel', '')
        else:
            _dbg(f'Create failed: HTTP {cr.status_code} - {cr.text}'); return [{'json': {'statusCode': 200, 'body': {'status': 'error', 'error': f'Failed to create Company node: HTTP {cr.status_code} - {cr.text}', 'debug': _debug_log}}}]
    except Exception as e:
        _dbg(f'Create exception: {e}\n{_tb.format_exc()}'); return [{'json': {'statusCode': 200, 'body': {'status': 'error', 'error': f'Failed to create Company node: {e}', 'debug': _debug_log}}}]

if not node_id:
    _dbg(f'No node_id after creation'); return [{'json': {'statusCode': 200, 'body': {'status': 'error', 'error': 'Failed to get node ID after creation', 'debug': _debug_log}}}]

# Update the node with override fields
updates = {
    'nodeProperties.linkedin_url_override': linkedin_url,
    'nodeProperties.linkedin_override_at': now,
}

if mark_fp:
    updates['nodeProperties.linkedin_url_fp'] = True
    updates['nodeProperties.linkedin_company_url'] = ''
    updates['nodeProperties.linkedin_company_name'] = ''

if note:
    updates['nodeProperties.linkedin_override_note'] = note

try:
    r = req.put(f'{FLOWSINT_URL}/api/sketches/{sketch_id}/nodes/edit', headers=HJ,
                json={'nodeId': node_id, 'updates': updates}, timeout=10)
    if r.ok:
        return [{'json': {
            'statusCode': 200,
            'body': {
                'status': 'ok', 'debug': _debug_log,
                'message': f'Updated node {node_id} with LinkedIn override',
                'node_id': node_id,
                'node_label': node_label,
                'linkedin_url_override': linkedin_url,
                'linkedin_url_fp': mark_fp,
                'linkedin_override_note': note
            }
        }}]
    else:
        _dbg(f'Update failed: HTTP {r.status_code} - {r.text}'); return [{'json': {'statusCode': 200, 'body': {'status': 'error', 'error': f'Update failed: HTTP {r.status_code} - {r.text}', 'debug': _debug_log}}}]
except Exception as e:
    _dbg(f'Update exception: {e}\n{_tb.format_exc()}'); return [{'json': {'statusCode': 200, 'body': {'status': 'error', 'error': f'Update failed: {e}', 'debug': _debug_log}}}]
